class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        unordered_set<int> unique;
        for (int x : nums) {
            if (x < k) return -1;
            unique.insert(x);
        }
        return unique.size() - (unique.count(k) ? 1 : 0);
    }
};

class Solution {
    public int minOperations(int[] nums, int k) {
        Set<Integer> unique = new HashSet<>();
        for (int x : nums) {
            if (x < k) return -1;
            unique.add(x);
        }
        return unique.size() - (unique.contains(k) ? 1 : 0);
    }
}

var minOperations = function(nums, k) {
    const unique = new Set();
    for (const x of nums) {
        if (x < k) return -1;
        unique.add(x);
    }
    return unique.size - (unique.has(k) ? 1 : 0);
};
